\documentclass[conference]{IEEEtran}
\title{Wide-Area Damping Control for Interconnected Microgrids}
\author{
\IEEEauthorblockN{K. Adeyemi}
\IEEEauthorblockA{Department of Electrical Engineering\\
University of Lagos\\
Lagos, Nigeria\\
k.adeyemi@example.edu}
}
\begin{document}
\maketitle
\begin{abstract}
This paper studies wide-area damping control for clusters of
interconnected microgrids and reports a field trial on a three-feeder
test network.
\end{abstract}
\begin{IEEEkeywords}
microgrids, damping control, wide-area measurements, legacy SCADA, renewable curtailment
\end{IEEEkeywords}

\section{Introduction}
Clusters of interconnected microgrids oscillate against each other when
inverter-dominated interfaces exchange power over weak ties. Damping
these inter-area modes requires measurements from across the cluster.

\section{Test Network}
Fig.~\ref{fig:architecture} shows the measurement architecture across
the three feeders of the test network.
\begin{figure}
\centering
\fbox{\rule{0pt}{3cm}\rule{7cm}{0pt}}
\caption{Wide-area measurement architecture across the three feeders.}
\label{fig:architecture}
\end{figure}
The control loop closes once per damping cycle; the timing budget is
summarised in Fig.~\ref{fig:timing}.
\begin{figure}
\centering
\fbox{\rule{0pt}{3cm}\rule{7cm}{0pt}}
\caption{Control-loop timing budget for one damping cycle.}
\label{fig:timing}
\end{figure}
Both figures span the full text width and overflow a single column.

\section{Conclusion}
A two-level controller with wide-area feedback damped the dominant
inter-area mode within two cycles in all trials.
\end{document}

